krpano.action:
(function () {
  var params = new URLSearchParams(window.location.search);
  var id = params.get("id") || "laporan";

  if (!/^[A-Za-z0-9_-]{1,100}$/.test(id)) {
    console.error("Nama file PDF tidak valid:", id);
    return;
  }

  if (document.getElementById("report-pdf-viewer")) {
    return;
  }

  var pdfUrl =
    "https://ryanedua.github.io/verification-demo/files/" +
    encodeURIComponent(id) +
    ".pdf";

  var frame = document.createElement("iframe");
  frame.id = "report-pdf-viewer";
  frame.title = "Dokumen PDF: " + id;
  frame.src = pdfUrl;
  frame.style.cssText =
    "position:fixed;" +
    "top:0;" +
    "left:0;" +
    "width:100%;" +
    "height:100%;" +
    "border:0;" +
    "background:#fff;" +
    "z-index:2147483647;";

  document.body.appendChild(frame);
  console.log("PDF viewer:", pdfUrl);
}());
